/**
 * Phase 4 Pipeline — Stage 4: Infrastructure Adapter Generator
 *
 * Generates infrastructure adapters that bridge DDD port interfaces to ERP
 * and database clients. One adapter is produced per port file found in the
 * Phase 3 project output. Also generates shared connection pool, IAM helper,
 * and telemetry wrapper files.
 *
 * Supported languages:
 *   typescript  — class implementing the port interface
 *   rust        — struct implementing the port trait
 *
 * Error codes:
 *   ECLI-P4-004  Adapter file write failure
 */

// Generated by Phase 4 pipeline — do not edit manually

import { existsSync, readdirSync, mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import type {
  Phase4Context,
  Phase4StageOutput,
  InfraAdapterOutput,
  AdapterFile,
  ERPResolution,
} from '../types.js';
import { createSpan, endSpan, emitSpan } from '../../phase2/telemetry.js';

// ============================================================================
// Constants
// ============================================================================

const DIR_MODE = 0o700;
const FILE_MODE = 0o600;

// ============================================================================
// Name Helpers
// ============================================================================

/**
 * Convert a PascalCase or mixed-case name to a kebab-case slug.
 */
function toKebab(name: string): string {
  return name
    .replace(/([a-z])([A-Z])/g, '$1-$2')
    .replace(/[^a-zA-Z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .toLowerCase();
}

/**
 * Convert a name to snake_case.
 */
function toSnake(name: string): string {
  return toKebab(name).replace(/-/g, '_');
}

/**
 * Convert a name to PascalCase.
 */
function toPascal(name: string): string {
  return name
    .replace(/(?:^|[-_\s])(\w)/g, (_, c: string) => (c as string).toUpperCase())
    .replace(/[^a-zA-Z0-9]/g, '');
}

/**
 * Derive a context slug from the context name (strips "Context" suffix).
 */
function toCtxSlug(contextName: string): string {
  return toKebab(contextName.replace(/Context$/i, ''));
}

/**
 * Derive a context snake_case name (strips "Context" suffix).
 */
function toCtxSnake(contextName: string): string {
  return toSnake(contextName.replace(/Context$/i, ''));
}

// ============================================================================
// TypeScript Adapter Code Generation
// ============================================================================

/**
 * Generate a TypeScript adapter class that implements a port interface.
 * The adapter accepts a database client and ERP client via constructor injection
 * and wraps each delegated call with a telemetry span.
 */
function generateTypescriptAdapter(
  portFileName: string,
  boundedContext: string,
  erpSystem: string,
  mockContract?: { methods: readonly { name: string; input: string; output: string; behavior: string }[] },
): string {
  const baseName = portFileName.replace(/\.ts$/, '');
  const className = toPascal(baseName) + 'Adapter';
  const interfaceName = 'I' + toPascal(baseName) + 'Port';
  const ctxSnake = toSnake(boundedContext);

  // Generate real method implementations from mock contract
  let methodImpls: string;
  if (mockContract && mockContract.methods.length > 0) {
    methodImpls = mockContract.methods
      .map((m) => {
        const methodName = m.name
          .replace(/(?:^|[-_ ])(\w)/g, (_, c: string) => (c as string).toUpperCase())
          .replace(/[^a-zA-Z0-9]/g, '');
        const camelName = methodName.charAt(0).toLowerCase() + methodName.slice(1);
        return [
          ``,
          `  /** ${m.behavior} */`,
          `  async ${camelName}(input: ${m.input || 'void'}): Promise<${m.output || 'void'}> {`,
          `    const span = createSpan('${ctxSnake}', '${baseName}.${camelName}', {});`,
          `    try {`,
          `      // Delegate to ERP client for ${erpSystem}`,
          `      const result = await (this.erpClient as { invoke: (op: string, data: unknown) => Promise<unknown> })`,
          `        .invoke('${camelName}', input);`,
          `      emitSpan(endSpan(span, 'ok', { operation: '${camelName}' }));`,
          `      return result as ${m.output || 'void'};`,
          `    } catch (err: unknown) {`,
          `      emitSpan(endSpan(span, 'error', { error: String(err) }));`,
          `      throw err;`,
          `    }`,
          `  }`,
        ].join('\n');
      })
      .join('\n');
  } else {
    // Fallback: generate standard CRUD methods
    methodImpls = [
      ``,
      `  async findById(id: string): Promise<Record<string, unknown> | null> {`,
      `    const span = createSpan('${ctxSnake}', '${baseName}.findById', { id });`,
      `    try {`,
      `      const result = await (this.dbClient as { query: (sql: string, params: unknown[]) => Promise<unknown[]> })`,
      `        .query('SELECT * FROM ${toSnake(baseName)} WHERE id = $1', [id]);`,
      `      emitSpan(endSpan(span, 'ok', { found: result !== null }));`,
      `      return (result as Record<string, unknown>[])?.[0] ?? null;`,
      `    } catch (err: unknown) {`,
      `      emitSpan(endSpan(span, 'error', { error: String(err) }));`,
      `      throw err;`,
      `    }`,
      `  }`,
      ``,
      `  async save(data: Record<string, unknown>): Promise<void> {`,
      `    const span = createSpan('${ctxSnake}', '${baseName}.save', { id: String(data['id'] ?? 'new') });`,
      `    try {`,
      `      await (this.dbClient as { execute: (sql: string, params: unknown[]) => Promise<void> })`,
      `        .execute('INSERT INTO ${toSnake(baseName)} (id) VALUES ($1) ON CONFLICT (id) DO UPDATE SET updated_at = NOW()', [data['id']]);`,
      `      emitSpan(endSpan(span, 'ok', {}));`,
      `    } catch (err: unknown) {`,
      `      emitSpan(endSpan(span, 'error', { error: String(err) }));`,
      `      throw err;`,
      `    }`,
      `  }`,
    ].join('\n');
  }

  return [
    `// Generated by Phase 4 pipeline — do not edit manually`,
    ``,
    `import type { ${interfaceName} } from '../ports/${baseName}.js';`,
    `import { createSpan, endSpan, emitSpan } from '../../../../pipeline/phase2/telemetry.js';`,
    ``,
    `/**`,
    ` * Infrastructure adapter: ${className}`,
    ` * Bounded context: ${boundedContext}`,
    ` * ERP system: ${erpSystem}`,
    ` *`,
    ` * Bridges the ${interfaceName} port to the ${erpSystem} ERP system`,
    ` * and the underlying database client.`,
    ` */`,
    `export class ${className} implements ${interfaceName} {`,
    `  constructor(`,
    `    private readonly dbClient: { query: (sql: string, params: unknown[]) => Promise<unknown[]>; execute: (sql: string, params: unknown[]) => Promise<void> },`,
    `    private readonly erpClient: { invoke: (operation: string, data: unknown) => Promise<unknown> },`,
    `  ) {}`,
    methodImpls,
    `}`,
    ``,
  ].join('\n');
}

/**
 * Generate a TypeScript connection pool configuration file.
 */
function generateTypescriptConnectionPool(erpSystem: string, dialect: string | null): string {
  return [
    `// Generated by Phase 4 pipeline — do not edit manually`,
    ``,
    `/**`,
    ` * Connection Pool Configuration`,
    ` * ERP system: ${erpSystem}`,
    ` * SQL dialect: ${dialect ?? 'N/A (API-only)'}`,
    ` *`,
    ` * TODO: Replace placeholder values with environment-sourced config.`,
    ` */`,
    `export interface ConnectionPoolConfig {`,
    `  readonly host: string;`,
    `  readonly port: number;`,
    `  readonly database: string;`,
    `  readonly user: string;`,
    `  readonly password: string;`,
    `  readonly maxConnections: number;`,
    `  readonly idleTimeoutMs: number;`,
    `  readonly ssl: boolean;`,
    `}`,
    ``,
    `export function buildConnectionPoolConfig(): ConnectionPoolConfig {`,
    `  return {`,
    `    // TODO: load from environment variables or Secret Manager`,
    `    host: process.env['DB_HOST'] ?? 'localhost',`,
    `    port: Number(process.env['DB_PORT'] ?? 5432),`,
    `    database: process.env['DB_NAME'] ?? '${toSnake(erpSystem)}',`,
    `    user: process.env['DB_USER'] ?? '',`,
    `    password: process.env['DB_PASSWORD'] ?? '',`,
    `    maxConnections: Number(process.env['DB_MAX_CONNECTIONS'] ?? 10),`,
    `    idleTimeoutMs: Number(process.env['DB_IDLE_TIMEOUT_MS'] ?? 30000),`,
    `    ssl: process.env['DB_SSL'] !== 'false',`,
    `  };`,
    `}`,
    ``,
  ].join('\n');
}

/**
 * Generate a TypeScript IAM helper that fetches a GCP identity token.
 */
function generateTypescriptIAMHelper(): string {
  return [
    `// Generated by Phase 4 pipeline — do not edit manually`,
    ``,
    `/**`,
    ` * GCP Identity Token Helper`,
    ` *`,
    ` * Fetches a short-lived identity token from the GCP metadata server`,
    ` * for service-to-service authentication.`,
    ` *`,
    ` * TODO: Replace audience with the actual Cloud Run service URL.`,
    ` */`,
    ``,
    `const METADATA_TOKEN_URL =`,
    `  'http://metadata.google.internal/computeMetadata/v1/instance/service-accounts/default/identity';`,
    ``,
    `/**`,
    ` * Fetch a GCP identity token for the given audience (Cloud Run URL).`,
    ` * Requires the service to run on GCP with an attached service account.`,
    ` */`,
    `export async function fetchIdentityToken(audience: string): Promise<string> {`,
    `  // TODO: use node-fetch or native fetch; handle token caching`,
    `  const url = \`\${METADATA_TOKEN_URL}?audience=\${encodeURIComponent(audience)}&format=full\`;`,
    ``,
    `  const response = await fetch(url, {`,
    `    headers: { 'Metadata-Flavor': 'Google' },`,
    `  });`,
    ``,
    `  if (!response.ok) {`,
    `    throw new Error(`,
    `      \`ECLI-P4-IAM: Failed to fetch identity token: HTTP \${response.status}\`,`,
    `    );`,
    `  }`,
    ``,
    `  return response.text();`,
    `}`,
    ``,
  ].join('\n');
}

/**
 * Generate a TypeScript telemetry wrapper for adapter operations.
 */
function generateTypescriptTelemetryWrapper(): string {
  return [
    `// Generated by Phase 4 pipeline — do not edit manually`,
    ``,
    `/**`,
    ` * Telemetry Wrapper for Infrastructure Adapters`,
    ` *`,
    ` * Re-exports the core telemetry helpers and provides a convenience`,
    ` * wrapper for wrapping async operations with span tracking.`,
    ` */`,
    ``,
    `export { createSpan, endSpan, emitSpan } from '../../../../pipeline/phase2/telemetry.js';`,
    ``,
    `/**`,
    ` * Wrap an async operation with a telemetry span.`,
    ` * Emits the span on both success and failure.`,
    ` */`,
    `export async function withSpan<T>(`,
    `  stage: string,`,
    `  operation: string,`,
    `  attributes: Record<string, string | number | boolean>,`,
    `  fn: () => Promise<T>,`,
    `): Promise<T> {`,
    `  const { createSpan, endSpan, emitSpan } = await import(`,
    `    '../../../../pipeline/phase2/telemetry.js'`,
    `  );`,
    `  const span = createSpan(stage, operation, attributes);`,
    `  try {`,
    `    const result = await fn();`,
    `    emitSpan(endSpan(span, 'ok', {}));`,
    `    return result;`,
    `  } catch (err: unknown) {`,
    `    emitSpan(endSpan(span, 'error', { error: String(err) }));`,
    `    throw err;`,
    `  }`,
    `}`,
    ``,
  ].join('\n');
}

