// ============================================================================
// Port File Discovery
// ============================================================================

/**
 * Find all port files for a bounded context within the Phase 3 project output.
 * Searches two candidate paths:
 *   - TypeScript: <phase3Dir>/project/src/<ctx-slug>/ports/
 *   - Rust:       <phase3Dir>/project/<ctx-snake>/src/ports/
 *
 * Excludes index.ts, mod.rs, and .gitkeep files.
 */
function discoverPortFiles(
  phase3Dir: string,
  contextName: string,
  language: 'typescript' | 'rust',
): string[] {
  const ctxSlug = toCtxSlug(contextName);
  const ctxSnake = toCtxSnake(contextName);

  const candidatePaths =
    language === 'typescript'
      ? [join(phase3Dir, 'project', 'src', ctxSlug, 'ports')]
      : [join(phase3Dir, 'project', ctxSnake, 'src', 'ports')];

  const excluded = new Set(['index.ts', 'mod.rs', '.gitkeep']);

  for (const portsDir of candidatePaths) {
    if (existsSync(portsDir)) {
      try {
        return readdirSync(portsDir).filter(
          (f) => !excluded.has(f) && (language === 'typescript' ? f.endsWith('.ts') : f.endsWith('.rs')),
        );
      } catch {
        // Directory unreadable — skip
      }
    }
  }

  return [];
}

// ============================================================================
// Main: generateInfraAdapters
// ============================================================================

/**
 * Stage 4: Generate infrastructure adapters for all seam port interfaces.
 *
 * For each bounded context in the Phase 2 domain model, discovers port files
 * in the Phase 3 project output and generates a corresponding adapter file.
 * Also generates shared infrastructure files:
 *   - connection-pool.ts / connection_pool.rs
 *   - iam-helper.ts / iam_helper.rs
 *   - telemetry-wrapper.ts / telemetry_wrapper.rs
 *
 * @param context - The Phase 4 pipeline context
 * @returns Stage output describing success or failure
 */
export function generateInfraAdapters(context: Phase4Context): Phase4StageOutput {
  const rootSpan = createSpan('infra-adapter-generation', 'generate-adapters', {
    phase4Dir: context.phase4Dir,
    phase3Dir: context.phase3Dir,
  });

  try {
    // -------------------------------------------------------------------------
    // Step 1: Retrieve ERP resolution and implementation language
    // -------------------------------------------------------------------------
    const erpStage = context.stageOutputs.get('erp-target-resolution');
    if (!erpStage || erpStage.status !== 'completed') {
      throw new Error(
        'ECLI-P4-004: ERP target resolution not available on context. ' +
        'Ensure the erp-target-resolution stage completed successfully.',
      );
    }
    const erpResolution = erpStage.data as ERPResolution;
    const language = context.phase3Artifacts.implementationLanguage;

    // -------------------------------------------------------------------------
    // Step 2: Retrieve Phase 2 domain model and TDD mock contracts
    // -------------------------------------------------------------------------
    const domainModel = context.phase3Artifacts.phase2Artifacts.domainModel;
    const tddPlan = context.phase3Artifacts.phase2Artifacts.tddPlan;
    const mockContracts = tddPlan?.mockContracts ?? [];
    const adapterFiles: AdapterFile[] = [];
    const writtenPaths: string[] = [];
    let totalAdapters = 0;

    // -------------------------------------------------------------------------
    // Step 3: Generate adapters per bounded context
    // -------------------------------------------------------------------------
    for (const ctx of domainModel.contexts) {
      const ctxSlug = toCtxSlug(ctx.name);
      const ctxSpan = createSpan(
        'infra-adapter-generation',
        `generate-adapters-${ctxSlug}`,
        { context: ctx.name, language },
        rootSpan.spanId,
      );

      try {
        // Discover port files for this context
        const portFiles = discoverPortFiles(context.phase3Dir, ctx.name, language);

        for (const portFile of portFiles) {
          // Find matching mock contract for this port file
          const portBaseName = portFile.replace(/\.(ts|rs)$/, '');
          const matchingContract = mockContracts.find((mc) => {
            const mcSlug = mc.interfaceName
              .replace(/([a-z])([A-Z])/g, '$1-$2')
              .replace(/[^a-zA-Z0-9]+/g, '-')
              .replace(/^-|-$/g, '')
              .toLowerCase();
            return mcSlug === portBaseName || mc.interfaceName === portBaseName;
          });

          const adapterContent =
            language === 'typescript'
              ? generateTypescriptAdapter(portFile, ctx.name, erpResolution.erpSystem, matchingContract)
              : generateRustAdapter(portFile, ctx.name, erpResolution.erpSystem);

          const adapterFileName =
            language === 'typescript'
              ? portFile.replace(/\.ts$/, '-adapter.ts')
              : portFile.replace(/\.rs$/, '_adapter.rs');

          const adapterRelPath =
            language === 'typescript'
              ? `project/src/${ctxSlug}/infra/${adapterFileName}`
              : `project/${toCtxSnake(ctx.name)}/src/infra/${adapterFileName}`;

          const adapterAbsPath = join(context.phase4Dir, adapterRelPath);
          const adapterDir = join(context.phase4Dir, language === 'typescript'
            ? `project/src/${ctxSlug}/infra`
            : `project/${toCtxSnake(ctx.name)}/src/infra`);

          mkdirSync(adapterDir, { recursive: true, mode: DIR_MODE });
          writeFileSync(adapterAbsPath, adapterContent, { encoding: 'utf-8', mode: FILE_MODE });

          writtenPaths.push(adapterAbsPath);
          totalAdapters++;

          adapterFiles.push({
            relativePath: adapterRelPath,
            content: adapterContent,
            kind: 'adapter',
            boundedContext: ctx.name,
            portInterface: portFile.replace(/\.(ts|rs)$/, ''),
          });
        }

        const finalCtxSpan = endSpan(ctxSpan, 'ok', {
          context: ctx.name,
          adaptersGenerated: portFiles.length,
        });
        emitSpan(finalCtxSpan);
        context.telemetrySpans.push(finalCtxSpan);
      } catch (err: unknown) {
        const finalCtxSpan = endSpan(ctxSpan, 'error', {
          context: ctx.name,
          error: err instanceof Error ? err.message : String(err),
        });
        emitSpan(finalCtxSpan);
        context.telemetrySpans.push(finalCtxSpan);
        throw err;
      }
    }

    // -------------------------------------------------------------------------
    // Step 4: Generate shared infrastructure files
    // -------------------------------------------------------------------------
    const sharedInfraDir = join(context.phase4Dir, 'project', 'src', 'infra');
    mkdirSync(sharedInfraDir, { recursive: true, mode: DIR_MODE });

    const sharedFiles: Array<{ name: string; content: string }> =
      language === 'typescript'
        ? [
            {
              name: 'connection-pool.ts',
              content: generateTypescriptConnectionPool(
                erpResolution.erpSystem,
                erpResolution.sqlDialect,
              ),
            },
            { name: 'iam-helper.ts', content: generateTypescriptIAMHelper() },
            { name: 'telemetry-wrapper.ts', content: generateTypescriptTelemetryWrapper() },
          ]
        : [
            {
              name: 'connection_pool.rs',
              content: generateRustConnectionPool(
                erpResolution.erpSystem,
                erpResolution.sqlDialect,
              ),
            },
            { name: 'iam_helper.rs', content: generateRustIAMHelper() },
            { name: 'telemetry_wrapper.rs', content: generateRustTelemetryWrapper() },
          ];

    let connectionPoolConfig = '';

    for (const sf of sharedFiles) {
      const absPath = join(sharedInfraDir, sf.name);
      writeFileSync(absPath, sf.content, { encoding: 'utf-8', mode: FILE_MODE });
      writtenPaths.push(absPath);

      if (sf.name.includes('connection-pool') || sf.name.includes('connection_pool')) {
        connectionPoolConfig = sf.content;
      }
    }

    // -------------------------------------------------------------------------
    // Step 5: Build and return stage output
    // -------------------------------------------------------------------------
    const infraAdapterOutput: InfraAdapterOutput = {
      adapters: adapterFiles,
      totalAdapters,
      connectionPoolConfig,
    };

    const finalRootSpan = endSpan(rootSpan, 'ok', {
      language,
      totalAdapters,
      sharedFiles: sharedFiles.length,
      contexts: domainModel.contexts.length,
    });
    emitSpan(finalRootSpan);
    context.telemetrySpans.push(finalRootSpan);

    const timing = finalRootSpan.durationMs ?? 0;

    const output: Phase4StageOutput = {
      stage: 'infra-adapter-generation',
      status: 'completed',
      data: infraAdapterOutput,
      artifacts: writtenPaths,
      timing,
      summary:
        `  [OK] Generated ${totalAdapters} infrastructure adapter(s) ` +
        `and ${sharedFiles.length} shared infra files ` +
        `(language=${language}, erp=${erpResolution.erpSystem}) ` +
        `across ${domainModel.contexts.length} bounded context(s) in ${timing}ms`,
    };

    context.stageOutputs.set('infra-adapter-generation', output);
    return output;
  } catch (err: unknown) {
    const errorMessage = err instanceof Error ? err.message : String(err);

    const finalRootSpan = endSpan(rootSpan, 'error', { error: errorMessage });
    emitSpan(finalRootSpan);
    context.telemetrySpans.push(finalRootSpan);

    const timing = finalRootSpan.durationMs ?? 0;

    const output: Phase4StageOutput = {
      stage: 'infra-adapter-generation',
      status: 'failed',
      data: { error: errorMessage },
      artifacts: [],
      timing,
      summary: `  [FAIL] Infrastructure adapter generation failed: ${errorMessage}`,
    };

    context.stageOutputs.set('infra-adapter-generation', output);
    return output;
  }
}
